uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
  vec3 color = mix(led.color, 0.8, speed);
  vec3 trail[led.count] = mix(color, 0.7, led.s);
  for (int i=0; i < led.count; i++) {
    trail[i] += vec3(0.1, 0.2, 0.3);
  }
}
vec3 shade(Led led) {
  return mix(color, 0.6, led.s);

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
    vec3 current_color = vec3(1.0, 0.0, 0.0);
    for (int i = 0; i < frame; i++) {
        float brightness = smoothstep(0.5, 2.0, dt * speed);
        current_color = mix(current_color, vec3(brightness), 1.0 - brightness);
    }
    trail[led.idx] = current_color;
}
vec3 shade(Led led) {
    return vec3(1.0, 0.0, 0.0);
